import { describe, it, expect } from "vitest";
import { runStrategy12dot10dot1 } from "../strategy12dot10dot1";
import type { Candle } from "../../../backtest";

describe("Strategy 12.10.1 Bug Reproduction", () => {
  it("BUG REPRO: Should enforce alternating logic after SL even if exit candle is in zone (multi-candle)", () => {
    // Setup candles
    // Start Price: 100
    // Trigger: 10 -> Long > 110, Short < 90
    // SL: 10 -> Long SL = 100 (110-10)

    const candles: Candle[] = [
      // 9:30 - Setup
      { time: "09:30:00", open: 100, high: 105, low: 95, close: 100, volume: 1000 },

      // 9:31 - Trigger Long (High 115 > 110)
      { time: "09:31:00", open: 105, high: 115, low: 105, close: 112, volume: 1000 },

      // 9:32 - Hit SL (Low 98 < 100)
      // Note: This candle is "In Zone" (90-110) because Low 98 > 90 and < 110.
      // This is a MULTI-CANDLE trade (Entry 9:31, Exit 9:32).
      { time: "09:32:00", open: 112, high: 113, low: 98, close: 99, volume: 1000 },

      // 9:33 - Trigger Long Again (High 115 > 110)
      // If alternating logic works, this should be IGNORED (must be Short).
      // If bug exists, this will take a Long trade.
      { time: "09:33:00", open: 99, high: 115, low: 99, close: 112, volume: 1000 },

      // 9:34 - Just filler
      { time: "09:34:00", open: 112, high: 112, low: 112, close: 112, volume: 1000 },
    ];

    const results = runStrategy12dot10dot1(
      candles,
      100, // Start Price
      10,  // Trigger Pts
      20,  // PT
      10,  // SL
      5,   // Max Round Trips
      true // Enable logging
    );

    // Analyze results
    const trades = results.filter(r => r.type.includes("Open"));

    // WITH BUG: We expect 2 trades (Long, then Long again)
    // WITH FIX: We expect 1 trade (Long, then Short required so 2nd Long ignored)

    console.log("Trades found:", trades.length);
    trades.forEach((t, i) => console.log(`Trade ${i+1}: ${t.type} at ${t.timestamp}`));

    // Assert that we DO NOT have a second long trade immediately
    // If trades.length === 2, it means the bug is present (it allowed a 2nd long)
    // So we expect trades.length to be 1 (or the 2nd trade to be Short, but in this data only Long trigger is hit)

    expect(trades.length).toBe(1);
  });
});

/**
 * Scan candles for re-eligibility (price must return between triggers).
 * 
 * **What this function does:**
 * After a trade exits, price must return to the zone between triggers before
 * another trade can be triggered. This prevents immediate re-entry when price
 * is still beyond a trigger.
 * 
 * **Re-eligibility Zone:**
 * Price is "between triggers" if: shortTrigger < price < longTrigger
 * 
 * **Same-Candle Eligibility:**
 * If the exit candle itself has price in the zone, we mark it as eligible
 * and override alternating logic for immediate reentry.
 * 
 * **9:35 Transition Handling:**
 * If we cross 9:35 during re-eligibility scan, we reset session state and
 * recalculate triggers.
 * 
 * **Returns:**
 * - Index of candle where re-eligibility was found
 * - -1 if re-eligibility not found (no more trades possible)
 * 
 * @param exitCandleIndex - Index of candle where trade exited
 * @param state - Trading state object (will be modified)
 * @returns Re-eligibility candle index, or -1 if not found
 */
function scanForReeligibility(
  exitCandleIndex: number,
  state: TradingState
): number {
  // Check exit candle itself for re-eligibility (same-candle exit fix)
  // When exit happens on the same candle as entry, or when exit candle has price
  // between triggers, we should check that candle for re-eligibility
  const exitCandle = state.candles[exitCandleIndex];
  if (state.enableLogging) {
    state.logReentry.debug("checking exit candle", {
      exitCandleIndex,
      exitCandle: {
        open: exitCandle.open,
        high: exitCandle.high,
        low: exitCandle.low,
        close: exitCandle.close,
      },
      shortTrigger: state.shortTrigger,
      longTrigger: state.longTrigger,
    }, undefined, "12dot10checkexit");
  }

  // Check if exit candle has price in zone (between triggers)
  const exitLowInZone = exitCandle.low > state.shortTrigger && exitCandle.low < state.longTrigger;
  const exitHighInZone = exitCandle.high > state.shortTrigger && exitCandle.high < state.longTrigger;
  const exitOpenInZone = exitCandle.open > state.shortTrigger && exitCandle.open < state.longTrigger;
  const exitCloseInZone = exitCandle.close > state.shortTrigger && exitCandle.close < state.longTrigger;

  if (exitLowInZone || exitHighInZone || exitOpenInZone || exitCloseInZone) {
    // Exit candle has price in zone - can check for reentry
    if (state.enableLogging) {
      state.logReentry.debug("re-eligibility on exit candle", {
        exitCandleIndex,
        exitLowInZone,
        exitHighInZone,
        exitOpenInZone,
        exitCloseInZone,
      }, undefined, "12dot10exiteligible");
    }
    state.log(`  Re-eligibility found on exit candle[${exitCandleIndex}] - price between triggers`);
    // Mark that exit candle was eligible (overrides alternating logic for immediate reentry)
    state.lastExitWasSameCandleEligible = true;
    const isSameCandle = (exitCandleIndex === state.scanStartIndex);
    if (isSameCandle) {
      state.log(`  Same-candle exit with eligible price - alternating logic will be overridden for next trade`);
    } else {
      state.log(`  Exit candle has eligible price - alternating logic will be overridden for next trade`);
    }
    // Return exit candle index (caller will set scanStartIndex to exitCandleIndex + 1)
    return exitCandleIndex;
  } else {
    if (state.enableLogging) {
      state.logReentry.debug("exit candle not eligible", { exitCandleIndex }, undefined, "12dot10exitnoteligible");
    }
    state.lastExitWasSameCandleEligible = false; // Reset flag
  }

  // Otherwise, proceed with normal re-eligibility scan from exitCandleIndex + 1
  for (let i = exitCandleIndex + 1; i < state.candles.length; i++) {
    const candle = state.candles[i];

    // Check cutoff time - no new entries after cutoff
    if (!isBeforeCutoff(candle.time, state.cutoffTime)) {
      state.log(`  Cutoff time ${state.cutoffTime} reached during re-eligibility scan, no more trades allowed`);
      break;
    }

    // Check if we need to switch start price during re-eligibility scan
    if (!state.hasSwitched && state.candle935Index >= 0 && i >= state.candle935Index && state.priceAt935 != null) {
      state.currentStartPrice = state.priceAt935;
      state.hasSwitched = true;

      // Reset logic during re-eligibility if 9:35 is crossed
      state.hasResetAt935 = true;
      state.sessionTradeCount = 0;
      state.lastTradeDirection = null;
      state.lastExitNote = null; // Reset exit note to clear alternating logic

      state.longTrigger = state.currentStartPrice + state.triggerPts;
      state.shortTrigger = state.currentStartPrice - state.triggerPts;
      state.log(`  *** 9:35 TRANSITION during re-eligibility scan ***`);
      state.log(`  Start price switched: ${state.startPrice} -> ${state.currentStartPrice}`);
      state.log(`  Triggers recalculated: Long=${state.longTrigger}, Short=${state.shortTrigger}`);
      state.log(`  Session reset triggered during re-eligibility`);
    }

    // Price is "between triggers" if the candle's range crosses the zone
    // i.e., at some point during the candle, price was between triggers
    // This means: candle.low < longTrigger AND candle.high > shortTrigger
    // AND the candle actually enters the zone (not just spanning both triggers)
    const lowInZone = candle.low > state.shortTrigger && candle.low < state.longTrigger;
    const highInZone = candle.high > state.shortTrigger && candle.high < state.longTrigger;
    const openInZone = candle.open > state.shortTrigger && candle.open < state.longTrigger;
    const closeInZone = candle.close > state.shortTrigger && candle.close < state.longTrigger;

    if (state.enableLogging) {
      state.logReentry.trace("checking reentry candle", {
        candleIndex: i,
        time: candle.time,
        candle: {
          open: candle.open,
          high: candle.high,
          low: candle.low,
          close: candle.close,
        },
        zone: { shortTrigger: state.shortTrigger, longTrigger: state.longTrigger },
        checks: { lowInZone, highInZone, openInZone, closeInZone },
      }, undefined, "12dot10checkreentry");
    }

    if (lowInZone || highInZone || openInZone || closeInZone) {
      if (state.enableLogging) {
        state.logReentry.debug("re-eligibility found", { candleIndex: i }, undefined, "12dot10reentryfound");
      }
      state.log(`  Re-eligibility found at candle[${i}] - price returned between triggers`);
      // Reset same-candle flag since this is a different-candle re-eligibility
      state.lastExitWasSameCandleEligible = false;
      return i;
    }
  }

  // No re-eligibility found
  if (state.enableLogging) {
    state.logReentry.debug("no re-eligibility found", undefined, undefined, "12dot10noreentry");
  }
  state.lastExitWasSameCandleEligible = false; // Reset flag
  return -1;
}

/**
 * =============================================================================
 * STRATEGY 12.10.1 - Stepped Stop Loss Implementation
 * =============================================================================
 * 
 * **This file contains ALL price calculation logic for strategy12.10.1.**
 * 
 * This strategy extends strategy12.10 with stepped stop loss functionality.
 * The stop loss moves up (for longs) or down (for shorts) to lock in profits
 * as price moves favorably, and when an adjusted SL is hit, we show enhanced metadata.
 * 
 * This strategy is based on strategy12dot10.ts with:
 * - Comprehensive structured logging with detailed JSDoc comments
 * - Improved organization (three sections: CONFIGURATION, MAIN/EXPORTED, HELPER FUNCTIONS)
 * - Scoped loggers for different subsystems
 * - Custom IDs on every log call for easy code lookup
 * - Proper log levels (INFO for milestones, DEBUG for decisions, TRACE for loops)
 * - Helper functions extracted for better maintainability
 * - TradingState interface for state management
 * - Stepped stop loss functionality
 * 
 * **KEY DIFFERENCE**: Direction change required after both SL and TP hits (not just SL).
 * **NEW FEATURE**: Stepped stop loss that adjusts to lock in profits at different thresholds.
 * 
 * ## Architecture Role
 * 
 * This is a **strategy implementation** - it contains the actual price calculation
 * logic that gets executed when this strategy is selected.
 * 
 * **Call Flow:**
 * ```
 * UI/CLI → generateAlgoTrades() [backtest.ts]
 *   ↓
 * Strategy Registry → getStrategy("strategy12.10.1") [strategies/index.ts]
 *   ↓
 * This file → runStrategy12dot10dot1() [THIS FILE]
 *   ↓
 * Returns AlgoTradeRow[] with calculated prices
 * ```
 * 
 * ## Usage
 * 
 * This strategy is executed via the strategy registry:
 * 
 * ```typescript
 * import { generateAlgoTrades } from "@/lib/backtest";
 * const trades = await generateAlgoTrades({
 *   strategyId: "strategy12.10",
 *   candles: [...],
 *   startPrice: 100.0,
 *   triggerPts: 5,
 *   profitTargetPts: 20,
 *   stopLossPts: 10,
 * });
 * ```
 * 
 * ## Input
 * 
 * - `candles`: Array of OHLCV candles for the trading day
 * - `startPrice`: Initial start price (9:30 open, may shift at 9:35 AM ET)
 * - `triggerPts`: Points above/below start price to trigger entry
 * - `profitTargetPts`: Points from start price to take profit target
 * - `stopLossPts`: Points from trigger to stop loss
 * - `maxRoundTrips`: Maximum number of round-trip trades allowed (default: 1)
 * - `enableLogging`: Enable verbose console logging (default: false)
 * - `cutoffTime`: Time cutoff for trades in HH:MM format (default: "09:45")
 * 
 * ## Happy Path Flow (inputs ➜ outputs per step)
 * 
 * 1) `find935CandleIndex()` - Input: candles array. Output: Index of 9:35 candle or -1
 * 2) `initializeTradingState()` - Input: config params. Output: Trading state object
 * 3) `check935Reset()` - Input: current state, candle index. Output: Updated state if reset needed
 * 4) `scanForTrigger()` - Input: candles, start index, triggers, state. Output: Trigger result or null
 * 5) `calculateEntry()` - Input: trigger result, direction. Output: Entry price and timestamp
 * 6) `calculateTpAndSl()` - Input: direction, start price, triggers, config. Output: TP and SL prices
 * 7) `scanForExit()` - Input: candles, entry, TP, SL. Output: Exit result
 * 8) `buildTradeRows()` - Input: trade data, direction, entry/exit. Output: Open and Close AlgoTradeRow objects
 * 9) `scanForReeligibility()` - Input: candles, exit index, triggers. Output: Re-eligibility index or -1
 * 
 * ## Strategy Behavior
 * 
 * This strategy uses a **variable start price** that changes at 9:35 AM ET:
 * 
 * 1. **Before 9:35**: Uses the original start price (9:30 AM open candle price)
 * 2. **At/After 9:35**: Switches to the 9:35:00 1-second candle's open price as the new start price
 * 3. **At 9:35**: Resets round-trip trade counter and eligibility.
 * 4. **Force Close**: If a trade is open at 9:35, it is forced closed.
 * 
 * ## Impact on Calculations
 * 
 * When the start price shifts at 9:35, all derived values recalculate:
 * - **Long Trigger** = currentStartPrice + triggerPts
 * - **Short Trigger** = currentStartPrice - triggerPts  
 * - **TP Above** = currentStartPrice + profitTargetPts
 * - **TP Below** = currentStartPrice - profitTargetPts
 * - **SL Long** = longTrigger - stopLossPts
 * - **SL Short** = shortTrigger + stopLossPts
 * 
 * ## Output
 * 
 * Returns `AlgoTradeRow[]` - Array of trade rows (pairs of Open + Close rows)
 * Each trade has:
 * - Open row: Entry timestamp, price, direction
 * - Close row: Exit timestamp, price, direction, exit reason, net P&L
 * 
 * @module strategy12dot10dot1
 */

// =============================================================================
// CONFIGURATION
// =============================================================================

import type { Strategy } from "./types";
import type { AlgoTradeRow, Candle } from "../../backtest";
import {
  calculateEntrySlippage,
  calculateTpSlippage,
  calculateSlSlippage,
} from "../helpers/calculatePrice";
import { resolveIntrabarDirectional } from "../../intrabar/directional";
import { createLogger } from "../../logger";

/**
 * Module-level logger instance.
 * 
 * This creates a logger scoped to the "strategy12.10.1" module. All log entries
 * from this file will be tagged with module: "strategy12.10.1".
 * 
 * We use this logger to create function-scoped loggers (via logger.main() and
 * logger.helper()) which tag logs with specific function names for better
 * organization and filtering in the UI.
 */
const logger = createLogger("strategy12.10.1");

// =============================================================================
// MAIN / EXPORTED
// =============================================================================

/**
 * Main strategy execution function - orchestrates multi-round-trip trading.
 * 
 * **This is the entry point for all price calculations in strategy12.10.**
 * 
 * This function is called by `generateAlgoTrades()` in `backtest.ts` after looking up
 * this strategy from the registry. It orchestrates the entire trading process:
 * 
 * 1. Initializes trading state and finds 9:35 transition point
 * 2. Loops through multiple round-trip trades (up to maxRoundTrips)
 * 3. For each trade: scans for trigger, calculates entry, scans for exit
 * 4. Builds trade rows and checks for re-eligibility before next trade
 * 5. Returns all generated trade rows
 * 
 * **Design Pattern:**
 * This function follows the "slim main function" pattern from the styleguide.
 * It delegates all detailed logic to helper functions, keeping the main function
 * to ~5-6 high-level function calls. This makes the code easier to understand
 * and maintain.
 * 
 * @param candles - Array of OHLCV candles for the day
 * @param startPrice - The day's starting price (9:30 open, may shift at 9:35)
 * @param triggerPts - Points above/below start to trigger entry
 * @param profitTargetPts - Points from start to take profit
 * @param stopLossPts - Points from trigger to stop loss
 * @param maxRoundTrips - Maximum number of round-trip trades allowed
 * @param enableLogging - Enable verbose console logging
 * @param cutoffTime - Time cutoff for trades (HH:MM format, e.g., "09:45")
 * @returns Array of AlgoTradeRow objects (pairs of Open + Close rows)
 */
export function runStrategy12dot10dot1(
  candles: Candle[],
  startPrice: number,
  triggerPts: number,
  profitTargetPts: number,
  stopLossPts: number,
  maxRoundTrips: number = 1,
  enableLogging: boolean = false,
  cutoffTime: string = "09:45",
  stopLossByProfitThreshold?: Record<string, number>
): AlgoTradeRow[] {
  // Create main function logger - this tags all logs from this function
  // with functionType: "main" and functionName: "runStrategy12dot10dot1"
  const logMain = logger.main("runStrategy12dot10dot1");

  /**
   * Logs function entry with input parameters and configuration.
   * INFO level: Major milestone - function start.
   * 
   * @param message - "starting, configuration loaded, Candles loaded"
   * @param data - Input candle count/start price and full config (triggerPts, profitTargetPts, etc.)
   * @param id - "12dot10start" - Custom ID for easy code lookup
   */
  logMain.info("starting, configuration loaded, Candles loaded", {
    input: {
      candleCount: candles.length,
      startPrice,
    },
    config: {
      triggerPts,
      profitTargetPts,
      stopLossPts,
      maxRoundTrips,
      cutoffTime,
    },
  }, "12dot10start"); // Custom ID for easy code lookup

  // Guard: Need at least 1 candle
  if (!candles.length) {
    /**
     * Logs fatal error when no candles are provided.
     * ERROR level: Fatal condition - function cannot proceed without candles.
     * 
     * @param message - "no candles provided"
     * @param data - Error details with message explaining empty array
     * @param id - "12dot10nocandles" - Custom ID for easy code lookup
     */
    logMain.error("no candles provided", { error: { message: "Empty candles array" } }, "12dot10nocandles"); // Custom ID for easy code lookup
    return [];
  }

  // Initialize trading state and find 9:35 transition point
  // This sets up all the state variables we'll use throughout the trading loop
  const initialState = initializeTradingState(
    candles,
    startPrice,
    triggerPts,
    profitTargetPts,
    stopLossPts,
    maxRoundTrips,
    enableLogging,
    cutoffTime,
    stopLossByProfitThreshold,
    logMain
  );

  // Execute multi-round-trip trading loop
  // This loop continues until we run out of candles, hit max round trips, or can't find more triggers
  const allRows = executeTradingLoop(initialState, logMain);

  /**
   * Logs function completion with output summary.
   * INFO level: Major milestone - function exit with results.
   * 
   * @param message - "completed"
   * @param data - Output summary: row count and round trips executed
     * @param id - "12dot10done" - Custom ID for easy code lookup
     */
  logMain.info("completed", {
    output: {
      rowCount: allRows.length,
      roundTrips: initialState.tradeNumber,
    },
  }, "12dot10done"); // Custom ID for easy code lookup

  return allRows;
}

