/**
 * CandleDecision interface for structured per-candle decision logging.
 * 
 * Captures all checks, conditional flags, outcome, and results for a single candle.
 * ONE log per candle aggregating checks from all phases (trigger-scan, exit-scan, reeligibility-scan).
 */
interface CandleDecision {
  candleIndex: number;
  candle: Candle;
  // Position tracking fields (at top of JSON as requested)
  entryPrice: number | null; // Entry price if there is a current position, null otherwise
  currentPrice: number | null; // Current price most favorable to the position (high for long, low for short)
  unrealizedEquity: number | null; // currentPrice - entryPrice (profit/loss from entry)
  checks: {
    cutoffTime: { passed: boolean; value: string; cutoff: string };
    triggerHit: { long: boolean; short: boolean; levels: { long: number; short: number } };
    alternatingLogic: { active: boolean; requiredDirection: "long" | "short" | null };
    reset935: { triggered: boolean; newStartPrice: number | null };
    exitHit?: { tp: boolean; sl: boolean; eod: boolean; levels?: { tp: number; sl: number } };
    reeligibility?: { eligible: boolean; priceBetweenTriggers: boolean };
  };
  conditionalFlags: {
    mustAlternate: boolean;
    allowedLongHit: boolean;
    allowedShortHit: boolean;
  };
  outcome: {
    decision: "TRADE_FOUND" | "NO_TRADE" | "CONTINUE_SCAN";
    reason: string;
    direction?: "long" | "short";
  };
  results: {
    tradesCreated: AlgoTradeRow[]; // Empty array if no trades created for this candle
  };
}

/**
 * Trading state object that tracks all mutable state during the trading loop.
 * 
 * **Why a state object?**
 * Instead of passing many individual variables between functions, we group
 * related state into an object. This makes function signatures cleaner and
 * makes it easier to see what state is being modified.
 * 
 * **State Categories:**
 * - Price state: currentStartPrice, triggers, hasSwitched
 * - Trade tracking: tradeNumber, sessionTradeCount, scanStartIndex
 * - Alternating logic: lastTradeDirection, lastExitNote, lastExitWasSameCandleEligible
 * - 9:35 reset: hasResetAt935, candle935Index, priceAt935
 * - Configuration: all the input parameters
 */
interface TradingState {
  // Price state
  currentStartPrice: number;
  longTrigger: number;
  shortTrigger: number;
  hasSwitched: boolean;

  // Trade tracking
  tradeNumber: number;
  sessionTradeCount: number;
  scanStartIndex: number;
  allRows: AlgoTradeRow[];

  // Alternating logic state
  lastTradeDirection: "long" | "short" | null;
  lastExitNote: "PT Hit" | "SL Hit" | "EOD Push" | "Forced 9:35 Close" | string | null;
  lastExitWasSameCandleEligible: boolean;

  // 9:35 reset state
  hasResetAt935: boolean;
  candle935Index: number;
  priceAt935: number | null;

  // Configuration (immutable)
  candles: Candle[];
  startPrice: number;
  triggerPts: number;
  profitTargetPts: number;
  stopLossPts: number;
  maxRoundTrips: number;
  enableLogging: boolean;
  cutoffTime: string;
  stopLossByProfitThreshold?: Record<string, number>;

  // Loggers (for structured logging)
  logTrigger: ReturnType<typeof logger.helper>;
  logExit: ReturnType<typeof logger.helper>;
  logReentry: ReturnType<typeof logger.helper>;
  logAlternate: ReturnType<typeof logger.helper>;
  logSteppedSL: ReturnType<typeof logger.helper>;
  log: (...args: any[]) => void; // Legacy console logger
}

/**
