import { describe, it, expect } from "vitest";
import { runStrategy12dot10dot1 } from "../strategy12dot10dot1";
import type { Candle } from "../../../backtest";

describe("Strategy 12.10.1 Bug Reproduction", () => {
  it("BUG REPRO: Should enforce alternating logic after SL even if exit candle is in zone (multi-candle)", () => {
    // Setup candles
    // Start Price: 100
    // Trigger: 10 -> Long > 110, Short < 90
    // SL: 10 -> Long SL = 100 (110-10)

    const candles: Candle[] = [
      // 9:30 - Setup
      { time: "09:30:00", open: 100, high: 105, low: 95, close: 100, volume: 1000 },

      // 9:31 - Trigger Long (High 115 > 110)
      { time: "09:31:00", open: 105, high: 115, low: 105, close: 112, volume: 1000 },

      // 9:32 - Hit SL (Low 98 < 100)
      // Note: This candle is "In Zone" (90-110) because Low 98 > 90 and < 110.
      // This is a MULTI-CANDLE trade (Entry 9:31, Exit 9:32).
      { time: "09:32:00", open: 112, high: 113, low: 98, close: 99, volume: 1000 },

      // 9:33 - Trigger Long Again (High 115 > 110)
      // If alternating logic works, this should be IGNORED (must be Short).
      // If bug exists, this will take a Long trade.
      { time: "09:33:00", open: 99, high: 115, low: 99, close: 112, volume: 1000 },

      // 9:34 - Just filler
      { time: "09:34:00", open: 112, high: 112, low: 112, close: 112, volume: 1000 },
    ];

    const results = runStrategy12dot10dot1(
      candles,
      100, // Start Price
      10,  // Trigger Pts
      20,  // PT
      10,  // SL
      5,   // Max Round Trips
      true // Enable logging
    );

    // Analyze results
    const trades = results.filter(r => r.type.includes("Open"));

    // WITH BUG: We expect 2 trades (Long, then Long again)
    // WITH FIX: We expect 1 trade (Long, then Short required so 2nd Long ignored)

    console.log("Trades found:", trades.length);
    trades.forEach((t, i) => console.log(`Trade ${i+1}: ${t.type} at ${t.timestamp}`));

    // Assert that we DO NOT have a second long trade immediately
    // If trades.length === 2, it means the bug is present (it allowed a 2nd long)
    // So we expect trades.length to be 1 (or the 2nd trade to be Short, but in this data only Long trigger is hit)

    expect(trades.length).toBe(1);
  });
});

